r.php'; } public function cloud_storage_settings($values) { if (isset($values[$this->guid])) { if (isset($values[$this->guid]['home'])) { $values[$this->guid]['home'] = preg_replace("/^\/*/", '', $values[$this->guid]['home']); $values[$this->guid]['home'] = preg_replace("/\/*$/", '', $values[$this->guid]['home']); } $GLOBALS['QC']->cache->delete_cache('kodexplorer-accessToken'); $GLOBALS['QC']->cache->delete_cache('kodexplorer-homePath'); } return $values; } public function get_desPath($subpath, $folder, $folder_path) { if (!$this->path) $this->getHomePath(); $subpath = $this->path . $subpath; return $subpath; } public function getHomePath() { $this->path = $GLOBALS['QC']->cache->get_cache('kodexplorer-homePath'); if (!$this->path) { try { if (!$this->operator) { if (!class_exists('kodexplorer\operator')) require QQWORLD_COLLECTOR_DIR . 'lib' . DIRECTORY_SEPARATOR . 'sdk' . DIRECTORY_SEPARATOR . 'kodexplorer' . DIRECTORY_SEPARATOR . 'operator.php'; $this->operator = new operator($this->home, $this->username, $this->password); } $this->path = $this->operator->getHomePath(); $GLOBALS['QC']->cache->set_cache('kodexplorer-homePath', $this->path); } catch ( Exception $e ) { if ($e->getMessage()) print '<div class="error"><p>' . $e->getMessage() . '</p></div>'; $GLOBALS['QC']->cache->set_cache('kodexplorer-homePath', ''); } } } public function access_service() { if (!$this->operator && $this->enabled && $this->is_current && !$this->accessed) { $this->includes(); $this->operator = new operator($this->home, $this->username, $this->password); $this->accessToken = $GLOBALS['QC']->cache->get_cache('kodexplorer-accessToken'); if ($this->accessToken) { $this->accessed = true; } else { try { $this->accessToken = $this->operator->getAccessToken(); $GLOBALS['QC']->cache->set_cache('kodexplorer-accessToken', $this->accessToken, 60); $this->accessed = true; } catch ( Exception $e ) { if ($e->getMessage()) print '<div class="error"><p>' . $e->getMessage() . '</p></div>'; $this->accessed = false; } } if ($this->accessed) $this->getHomePath(); } } public function is_object_exist($destination_path) { $this->access_service(); $destination_path = preg_replace('/^\/*/i', '', $destination_path); try { $fileInfo = $this->operator->getFileInfo($destination_path, 'file', $this->accessToken); return $fileInfo['isWriteable']; } catch ( Exception $e ) { return false; } } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; set_time_limit($this->options->qc_stress_timeout); if ($this->is_object_exist($destination_path)) { if ($this->options->cloud_storage_override) { $this->delete_object($destination_path); } else { return true; } } try { return $this->operator->uploadFile($source_path, $destination_path, $this->accessToken); } catch ( Exception $e ) { do_action( 'qqworld-collector-log', $this->log_id, 'kodexplorer failed: ', $e->getMessage() ); return false; } } public function delete_object($object) { $object = preg_replace('/^\/*/i', '', $object); try { return $this->operator->deleteFile($object, $this->accessToken); } catch ( Exception $e ) { return false; } } } ?>